using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using Memories.Gameplay.Reactions;using Memories.Gameplay.Interaction;
[InitializeOnLoad]public static class DockAudit{static DockAudit(){EditorApplication.delayCall+=Run;}static void Run(){if(File.Exists("Temp/DockAudit.txt"))return;try{var b=new StringBuilder();foreach(var path in AssetDatabase.GetAllAssetPaths().Where(p=>p.StartsWith("Assets/_Project/Configs/Reactions/Park/Cafe_")&&p.EndsWith(".asset"))){var g=AssetDatabase.LoadAssetAtPath<ReactionGraph>(path);b.AppendLine(path);foreach(var n in g.nodes){b.Append(g.nodes.IndexOf(n)+" "+n.GetType().Name+" ");if(n is ReactionNode a)b.Append(a.Kind+" key="+a.ObjectKey+" var="+a.VariableId+" text="+(a.TextGraph?a.TextGraph.name:"")+" graph="+(a.ReactionGraph?a.ReactionGraph.name:"")+" active="+a.Active+" wait="+a.WaitForLighting);foreach(var o in n.Outputs)b.Append(" "+o.fieldName+"->"+g.nodes.IndexOf(o.GetConnection(0)?.node));b.AppendLine();}}var all=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Transform>(true)).ToArray();foreach(var t in all){if(t.name.Contains("Лили")||t.name.Contains("Лодка")||t.GetComponent<LightingGroup>()||t.GetComponent<ParkCafeDissolveReaction>()){b.AppendLine(t.name+" pos="+t.position+" active="+t.gameObject.activeSelf);foreach(var c in t.GetComponents<MonoBehaviour>())if(c)b.AppendLine(EditorJsonUtility.ToJson(c));}}var lily=all.First(x=>x.name=="Лили — на причале");var go=UnityEngine.Object.Instantiate(lily.gameObject);go.transform.position=Vector3.zero;go.transform.rotation=Quaternion.identity;go.SetActive(true);var pvu=new PreviewRenderUtility();pvu.AddSingleGO(go);pvu.BeginStaticPreview(new Rect(0,0,600,800));pvu.camera.transform.position=new Vector3(0,1,-3);pvu.camera.transform.LookAt(new Vector3(0,.9f,0));pvu.camera.nearClipPlane=.01f;pvu.camera.farClipPlane=20;pvu.camera.orthographic=true;pvu.camera.orthographicSize=1.05f;pvu.lights[0].intensity=1.4f;pvu.lights[0].transform.rotation=Quaternion.Euler(30,180,0);pvu.lights[1].intensity=1;pvu.ambientColor=Color.gray;pvu.Render(true);File.WriteAllBytes("Temp/DockLilyReference.png",pvu.EndStaticPreview().EncodeToPNG());pvu.Cleanup();File.WriteAllText("Temp/DockAudit.txt",b.ToString());}catch(Exception e){File.WriteAllText("Temp/DockAudit.txt",e.ToString());}}}